const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=new Date(), ym=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`, month=ym(current), iso=()=>`${month}-${String(current.getDate()).padStart(2,'0')}`, monthName=(m=month)=>new Date(m+'-15T12:00:00').toLocaleDateString('es-CL',{month:'long',year:'numeric'}), date=d=>new Date(d+'T12:00:00').toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'});
const seed={people:[{id:'C001',name:'María González',email:'maria@example.com',phone:'+56 9 1234 5678',address:'Av. Providencia 1240, Santiago'},{id:'C002',name:'Carlos Mendoza',email:'carlos@example.com',phone:'+56 9 2345 6789',address:'Los Olivos 420, Santiago'},{id:'C003',name:'Ana Martínez',email:'ana@example.com',phone:'+56 9 3456 7890',address:'Santa Isabel 820, Santiago'},{id:'C004',name:'Diego Ramírez',email:'diego@example.com',phone:'+56 9 4567 8901',address:'Av. Italia 620, Santiago'},{id:'C005',name:'Sofía López',email:'sofia@example.com',phone:'+56 9 5678 9012',address:'Manuel Montt 340, Santiago'}],rooms:[{id:'I400901',name:'Habitación 01',property:'Casa Providencia',person:'C001',amount:280000,day:5,deposit:280000,guarantor:'C002',services:[['Cama','Matrimonial, base de madera'],['Aire acondicionado','Split 9.000 BTU'],['Clóset','Empotrado, dos puertas'],['Baño','Privado'],['Piso','Flotante'],['Pintura','Blanco, buen estado']]},{id:'I400902',name:'Habitación 02',property:'Casa Providencia',person:'C002',amount:250000,day:5,deposit:250000,guarantor:'C004',services:[['Cama','Una plaza'],['Baño','Compartido']]},{id:'I400903',name:'Habitación 03',property:'Casa Providencia',person:'C003',amount:300000,day:5,deposit:300000,services:[['Cama','Dos plazas'],['Baño','Privado']]},{id:'I400904',name:'Anexo 01',property:'Casa Ñuñoa',person:'C005',amount:350000,day:10,deposit:350000,services:[['Cocina','Equipada'],['Baño','Privado']]},{id:'I400905',name:'Habitación 04',property:'Casa Ñuñoa',person:null,amount:260000,day:5,services:[['Cama','Una plaza']]}],loans:[{id:'P0001',person:'C004',capital:1200000,rate:2,amount:224000,day:5,guarantor:'C002',investor:'Patrimonio Antonini'},{id:'P0002',person:'C001',capital:600000,rate:2,amount:112000,day:5,guarantor:'C005',investor:'Patrimonio Antonini'}],payments:[],settings:{email:'administracion@example.com',phone:'+56 9 8765 4321',interval:5,emailEnabled:true,whatsapp:false},outbox:[]};
for(let i=0;i<4;i++){let d=new Date(current.getFullYear(),current.getMonth()-i,5);let m=ym(d);for(const r of seed.rooms.filter(r=>r.person)){if(i===0&&['C001','C002'].includes(r.person))continue;seed.payments.push({id:crypto.randomUUID(),ref:r.id,period:m,date:m+'-05',amount:r.amount,capital:r.amount,interest:0})}for(const l of seed.loans){if(i===0&&l.id==='P0001')continue;seed.payments.push({id:crypto.randomUUID(),ref:l.id,period:m,date:m+'-06',amount:l.amount,capital:l.amount-l.capital*l.rate/100,interest:l.capital*l.rate/100})}}
let db;try{db=JSON.parse(localStorage.getItem('antonini-v1'))||seed}catch{db=seed}let page='dashboard', selected=null;const save=()=>localStorage.setItem('antonini-v1',JSON.stringify(db));const person=id=>db.people.find(p=>p.id===id), allAccounts=()=>[...db.rooms.filter(r=>r.person),...db.loans], account=id=>allAccounts().find(a=>a.id===id), paid=(id,m=month)=>db.payments.filter(p=>p.ref===id&&p.period===m).reduce((s,p)=>s+p.amount,0), balance=(a,m=month)=>Math.max(0,a.amount-paid(a.id,m)), late=a=>balance(a)>0&&current.getDate()>a.day, initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join(''), avatar=(p,orange=false)=>`<div class="avatar ${orange?'orange':''}">${initials(p.name)}</div>`, status=a=>`<span class="tag ${late(a)?'late':''}">${!balance(a)?'Al día':late(a)?'Pago atrasado':'Por pagar'}</span>`, total=arr=>arr.reduce((s,p)=>s+p.amount,0), navItems=[['dashboard','▦','Resumen general'],['rooms','⌂','Arriendos'],['loans','↗','Préstamos'],['payments','▤','Pagos'],['people','♙','Personas'],['alerts','◷','Cobranza'],['settings','⚙','Configuración']];
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function go(p,id=null){page=p;selected=id;render();window.scrollTo(0,0)}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">TU ADMINISTRACIÓN, MÁS SIMPLE</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function payButton(id=''){return `<button class="button primary" onclick="paymentModal('${id}')">＋ &nbsp; Registrar pago</button>`}
function render(){ $('#today').textContent=current.toLocaleDateString('es-CL',{day:'numeric',month:'short',year:'numeric'});$('#crumb').textContent=navItems.find(x=>x[0]===page)?.[2];$('#nav').innerHTML=navItems.map(([id,icon,label])=>`<button class="${page===id?'active':''}" onclick="go('${id}')"><span class="nav-icon">${icon}</span><span>${label}</span>${id==='alerts'?`<span class="count">${allAccounts().filter(late).length}</span>`:''}</button>`).join('');$('#content').innerHTML=({dashboard,rooms,loans,payments,people,alerts,settings}[page])();}
function paymentTable(list){return list.length?`<div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>CONCEPTO</th><th>FECHA DE PAGO</th><th>MONTO</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.map(p=>{let a=account(p.ref);let who=person(a?.person);return `<tr><td><div class="person-cell">${avatar(who)}<div><div class="row-name">${esc(who.name)}</div><div class="row-sub">${p.ref}</div></div></div></td><td><span class="tag ${a.name?'':'loan'}">${a.name?'Arriendo':'Préstamo'}</span><div class="row-sub">${esc(a.name||a.id)}</div></td><td>${date(p.date)}</td><td><b>${money(p.amount)}</b></td><td><span class="tag">● Registrado</span></td><td><button class="text-button" onclick="receipt('${p.id}')">Ver recibo ↗</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Todavía no hay pagos registrados.</div>'}
function dashboard(){const collected=total(db.payments.filter(p=>p.period===month)), due=allAccounts().reduce((s,a)=>s+balance(a),0), overdue=allAccounts().filter(late);return heading('Resumen general',`Una mirada a tu gestión. Esto es lo que pasa en ${monthName()}.`,`<button class="button" onclick="exportCSV()">↓ &nbsp; Exportar pagos</button>${payButton()}`)+`<div class="stats">${[['Ingresos del mes',money(collected),'↙','Pagos registrados este mes',''],['Pendiente de cobro',money(due),'◷',`${allAccounts().filter(a=>balance(a)).length} compromisos pendientes`,'warn'],['Habitaciones ocupadas',`${db.rooms.filter(r=>r.person).length} <span style="font-size:15px;color:#a7b3a5">/ ${db.rooms.length}</span>`,'⌂',`${db.rooms.filter(r=>!r.person).length} habitación disponible`,''],['Préstamos activos',db.loans.length,'↗',`${money(db.loans.reduce((s,l)=>s+loanRemaining(l),0))} de capital pendiente`,'']].map(([label,value,icon,foot,cls])=>`<div class="stat ${cls}"><div class="stat-title">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot"><b>${foot}</b></div></div>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Ingresos recibidos</h2><p>Evolución de arriendos y préstamos</p></div><span class="pill">Últimos 6 meses ⌄</span></div>${chart()}<div class="legend"><span><i></i>Arriendos</span><span><i class="light"></i>Préstamos</span></div></section><section class="panel"><div class="panel-heading"><div><h2>Requieren tu atención <span class="tag late">${overdue.length}</span></h2><p>Pagos vencidos de este mes</p></div><button class="text-button" onclick="go('alerts')">Ver todos ↗</button></div>${overdue.slice(0,3).map(a=>`<div class="alert-row" onclick="go('${a.name?'rooms':'loans'}','${a.id}')">${avatar(person(a.person),true)}<div><div class="row-name">${esc(person(a.person).name)}</div><div class="row-sub">${esc(a.name||'Préstamo '+a.id)}</div></div><div class="row-end">${money(balance(a))}<small>${current.getDate()-a.day} días de atraso</small></div></div>`).join('')||'<div class="empty">Todos los pagos están al día.</div>'}<div class="alert-footer">◷ &nbsp; Recordatorios configurados cada ${db.settings.interval} días · Sin conexión</div></section></div><section class="panel"><div class="panel-heading"><div><h2>Últimos pagos registrados</h2><p>Cada movimiento, en su lugar.</p></div><button class="text-button" onclick="go('payments')">Ver todos los pagos ↗</button></div>${paymentTable([...db.payments].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4))}<div class="table-footer"><span>Mostrando los 4 movimientos más recientes</span><span>Actualizado con tus registros</span></div></section><div class="bottom-note"><span style="font-size:22px">♧</span><div><b>Menos seguimiento manual. Más tranquilidad.</b><small>Prepara recordatorios y comprobantes con el historial de cada cliente.</small></div><button class="button" onclick="go('settings')">Configurar automatizaciones →</button></div>`}
function chart(){const months=Array.from({length:6},(_,i)=>ym(new Date(current.getFullYear(),current.getMonth()-5+i,1)));const series=months.map(m=>[total(db.payments.filter(p=>p.period===m&&p.ref.startsWith('I'))),total(db.payments.filter(p=>p.period===m&&p.ref.startsWith('P')))]);const max=Math.max(...series.flat(),1);return `<div class="chart"><div class="gridlines">${[1,.75,.5,.25,0].map(n=>`<div class="gridline"><span>${(max*n/1e6).toFixed(1)}M</span></div>`).join('')}</div><div class="bars">${series.map((s,i)=>`<div class="bar-group">${s.map((n,j)=>`<div class="bar ${j?'light':''}" style="height:${n/max*100}%" title="${j?'Préstamos':'Arriendos'}: ${money(n)}"></div>`).join('')}<label>${new Date(months[i]+'-15').toLocaleDateString('es',{month:'short'})}</label></div>`).join('')}</div></div>`}
function rooms(){if(selected)return roomDetail(selected);return heading('Arriendos','Habitaciones, contratos e inquilinos en un solo lugar.',`<button class="button primary" onclick="newRoom()">＋ Nueva habitación</button>`)+`<div class="toolbar"><input aria-label="Buscar habitación" placeholder="⌕  Buscar habitación, inmueble o inquilino…" oninput="filterCards(this.value)"></div><div class="room-grid">${db.rooms.map(r=>`<article class="panel room-card" data-search="${esc((r.name+' '+r.property+' '+(person(r.person)?.name||'')).toLowerCase())}" onclick="go('rooms','${r.id}')"><div class="room-top"><span class="room-symbol">⌂</span>${r.person?status(r):'<span class="tag">Disponible</span>'}</div><h3>${esc(r.name)}</h3><p>${esc(r.property)} · ${r.id}</p><div class="person-cell" style="margin-top:22px">${r.person?avatar(person(r.person)):''}<span>${esc(person(r.person)?.name||'Sin inquilino asignado')}</span></div><div class="room-bottom"><b>${money(r.amount)} <span style="font-weight:400;color:#99a694">/ mes</span></b><span class="link">Ver detalle →</span></div></article>`).join('')}</div>`}
function filterCards(q){document.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.includes(q.toLowerCase()))}
function roomDetail(id){const r=db.rooms.find(r=>r.id===id), p=person(r.person), linked=db.loans.filter(l=>l.person===r.person);return heading(r.name,`${esc(r.property)} · Contrato ${r.id}`,`<button class="button" onclick="go('rooms')">← Arriendos</button>${p?payButton(id):`<button class="button primary" onclick="assignTenant('${id}')">Asignar inquilino</button>`}`)+`<div class="detail-grid"><section class="panel detail-info"><div class="eyebrow">INQUILINO</div>${p?`<div class="person-cell">${avatar(p)}<div><b>${esc(p.name)}</b><div class="row-sub">${p.id}</div></div></div><div class="key-value"><span>Correo</span>${esc(p.email)}</div><div class="key-value"><span>Teléfono</span>${esc(p.phone)}</div><div class="key-value"><span>Estado</span>${status(r)}</div>`:'<p>Habitación disponible</p>'}<h3>Contrato de arriendo</h3><div class="key-value"><span>Mensualidad</span>${money(r.amount)}</div><div class="key-value"><span>Vencimiento</span>Día ${r.day} de cada mes</div><div class="key-value"><span>Depósito</span>${money(r.deposit||0)}</div><div class="key-value"><span>Aval</span>${esc(person(r.guarantor)?.name||'Sin aval')}</div><div class="key-value"><span>Pendiente del mes</span>${money(p?balance(r):0)}</div></section><div class="stack"><section class="panel"><div class="panel-heading"><div><h2>Equipamiento y entrega</h2><p>Detalle de lo que incluye esta habitación</p></div><button class="text-button" onclick="servicesModal('${id}')">Editar / agregar ＋</button></div><div style="padding:0 22px 20px">${r.services.map(([k,v])=>`<div class="key-value"><span>${esc(k)}</span>${esc(v)}</div>`).join('')}</div></section><section class="panel"><div class="panel-heading"><h2>Préstamos del inquilino</h2></div>${linked.length?linked.map(l=>`<div class="alert-row" onclick="go('loans','${l.id}')"><div><b>${l.id}</b><div class="row-sub">Capital pendiente: ${money(loanRemaining(l))} · Tasa ${l.rate}% mensual</div></div><div class="row-end">${status(l)}<small>Ver préstamo →</small></div></div>`).join(''):'<div class="empty">Este inquilino no tiene préstamos registrados.</div>'}</section><section class="panel"><div class="panel-heading"><h2>Historial de pagos de arriendo</h2></div>${paymentTable(db.payments.filter(p=>p.ref===id).sort((a,b)=>b.date.localeCompare(a.date)))}</section></div></div>`}
function loanRemaining(l){return Math.max(0,l.capital-db.payments.filter(p=>p.ref===l.id).reduce((s,p)=>s+p.capital,0))}
function loans(){if(selected)return loanDetail(selected);return heading('Préstamos','Controla el capital, los intereses y los compromisos de cada deudor.',`<button class="button primary" onclick="newLoan()">＋ Nuevo préstamo</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>DEUDOR / PRÉSTAMO</th><th>CAPITAL PENDIENTE</th><th>TASA MENSUAL</th><th>CUOTA</th><th>AVAL</th><th>ESTADO</th><th></th></tr></thead><tbody>${db.loans.map(l=>`<tr><td><div class="person-cell">${avatar(person(l.person))}<div><b>${esc(person(l.person).name)}</b><div class="row-sub">${l.id}</div></div></div></td><td><b>${money(loanRemaining(l))}</b><div class="progress"><span style="width:${(l.capital-loanRemaining(l))/l.capital*100}%"></span></div></td><td>${l.rate}%</td><td>${money(l.amount)}</td><td>${esc(person(l.guarantor)?.name||'Sin aval')}</td><td>${status(l)}</td><td><button class="text-button" onclick="go('loans','${l.id}')">Ver detalle →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function loanDetail(id){let l=account(id),p=person(l.person);return heading(`Préstamo ${id}`,`${esc(p.name)} · ${esc(l.investor)}`,`<button class="button" onclick="go('loans')">← Préstamos</button>${payButton(id)}`)+`<div class="detail-grid"><section class="panel detail-info"><h3>${esc(p.name)}</h3><div class="key-value"><span>Correo</span>${esc(p.email)}</div><div class="key-value"><span>Capital inicial</span>${money(l.capital)}</div><div class="key-value"><span>Capital pendiente</span>${money(loanRemaining(l))}</div><div class="key-value"><span>Tasa mensual</span>${l.rate}%</div><div class="key-value"><span>Cuota mensual</span>${money(l.amount)}</div><div class="key-value"><span>Aval responsable</span>${esc(person(l.guarantor)?.name||'Sin aval')}</div><div class="key-value"><span>Estado</span>${status(l)}</div></section><div class="stack"><section class="panel"><div class="panel-heading"><div><h2>Proyección de pagos · 6 meses</h2><p>Estimación con tasa mensual sobre saldo. No constituye un contrato.</p></div></div>${projection(l)}</section><section class="panel"><div class="panel-heading"><h2>Pagos realizados</h2></div>${paymentTable(db.payments.filter(p=>p.ref===id).sort((a,b)=>b.date.localeCompare(a.date)))}</section></div></div>`}
function projection(l){let remaining=loanRemaining(l);return `<div class="table-wrap"><table><thead><tr><th>VENCIMIENTO</th><th>CUOTA</th><th>CAPITAL</th><th>INTERÉS</th><th>ESTADO</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>{let m=ym(new Date(current.getFullYear(),current.getMonth()+i,1)),interest=Math.round(remaining*l.rate/100),capital=Math.min(remaining,Math.max(0,l.amount-interest)),amount=capital+interest;remaining-=capital;return `<tr><td>${date(m+'-'+String(l.day).padStart(2,'0'))}</td><td>${money(amount)}</td><td>${money(capital)}</td><td>${money(interest)}</td><td><span class="tag ${i===0&&late(l)?'late':''}">${i===0?(balance(l)?late(l)?'En mora':'Por pagar':'Pagado'):'Proyectado'}</span></td></tr>`}).join('')}</tbody></table></div>`}
function payments(){return heading('Registro de pagos','El historial completo de arriendos y préstamos.',`<button class="button" onclick="exportCSV()">↓ Exportar CSV</button>${payButton()}`)+`<div class="toolbar"><input id="payment-search" placeholder="⌕  Buscar por nombre o referencia…" oninput="filterPayments()" aria-label="Buscar pagos"><select id="payment-type" onchange="filterPayments()" aria-label="Tipo de pago"><option value="">Todos los conceptos</option><option value="I">Arriendos</option><option value="P">Préstamos</option></select></div><section class="panel" id="payments-table">${paymentTable([...db.payments].sort((a,b)=>b.date.localeCompare(a.date)))}</section>`}
function filterPayments(){let q=$('#payment-search').value.toLowerCase(),type=$('#payment-type').value;$('#payments-table').innerHTML=paymentTable(db.payments.filter(p=>p.ref.startsWith(type)&&(person(account(p.ref).person).name+' '+p.ref).toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date)))}
function people(){return heading('Personas','Un registro único para inquilinos, deudores y avales.',`<button class="button primary" onclick="newPerson()">＋ Agregar persona</button>`)+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>NOMBRE</th><th>CORREO</th><th>TELÉFONO</th><th>RELACIÓN</th></tr></thead><tbody>${db.people.map(p=>`<tr><td><div class="person-cell">${avatar(p)}<b>${esc(p.name)}</b></div></td><td>${esc(p.email)}</td><td>${esc(p.phone)}</td><td>${[db.rooms.some(r=>r.person===p.id)?'Inquilino':'',db.loans.some(l=>l.person===p.id)?'Deudor':'',allAccounts().some(a=>a.guarantor===p.id)?'Aval':''].filter(Boolean).map(r=>`<span class="tag">${r}</span>`).join(' ')||'Sin asignar'}</td></tr>`).join('')}</tbody></table></div></section>`}
function alerts(){let overdue=allAccounts().filter(late);return heading('Cobranza y recordatorios','Revisa los saldos vencidos y prepara el seguimiento de tus clientes.',`<button class="button primary" onclick="prepareReminders()">↗ Preparar recordatorios</button>`)+`<div class="notice">Modo demostración: los mensajes se guardan como borradores. No se envían correos ni WhatsApp. Frecuencia configurada: cada ${db.settings.interval} días.</div><section class="panel"><div class="panel-heading"><h2>Pendientes de este mes · ${monthName()}</h2><span class="tag late">${overdue.length} vencidos</span></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>CONCEPTO</th><th>PENDIENTE</th><th>ATRASO</th><th></th></tr></thead><tbody>${overdue.map(a=>`<tr><td><b>${esc(person(a.person).name)}</b><div class="row-sub">${esc(person(a.person).email)}</div></td><td>${esc(a.name||a.id)}</td><td>${money(balance(a))}</td><td><span class="tag late">${current.getDate()-a.day} días</span></td><td><button class="text-button" onclick="reminder('${a.id}')">Ver mensaje ↗</button></td></tr>`).join('')}</tbody></table></div>${!overdue.length?'<div class="empty">No hay pagos vencidos este mes.</div>':''}</section><section class="panel" style="margin-top:22px"><div class="panel-heading"><h2>Borradores de notificación</h2></div>${db.outbox.length?db.outbox.map(o=>`<div class="alert-row"><span>✉</span><div><b>${esc(o.subject)}</b><div class="row-sub">Para: ${esc(o.to)} · Copia: ${esc(db.settings.email)}</div></div><span class="row-end"><span class="tag loan">Borrador · Sin enviar</span></span></div>`).join(''):'<div class="empty">Al registrar un pago o preparar recordatorios, aparecerán aquí.</div>'}</section>`}
function settings(){return heading('Configuración','Define el contacto de administración y tus reglas de seguimiento.')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Automatizaciones de cobranza</h2></div><form class="settings-body" onsubmit="saveSettings(event)"><div class="notice">Conexiones pendientes. Se necesita un servidor, un proveedor de correo y WhatsApp Business para activar envíos programados.</div><label class="form-label">Frecuencia de recordatorios<select name="interval"><option value="5" ${db.settings.interval===5?'selected':''}>Cada 5 días</option><option value="3" ${db.settings.interval===3?'selected':''}>Cada 3 días</option><option value="7" ${db.settings.interval===7?'selected':''}>Cada 7 días</option></select></label><label class="check"><input type="checkbox" name="emailEnabled" ${db.settings.emailEnabled?'checked':''}> Preparar mensajes de correo</label><label class="check"><input type="checkbox" name="whatsapp" ${db.settings.whatsapp?'checked':''}> Preparar mensajes de WhatsApp</label><label class="form-label">Correo del administrador<input type="email" name="email" value="${esc(db.settings.email)}" required></label><label class="form-label">Teléfono de contacto<input name="phone" value="${esc(db.settings.phone)}" required></label><button class="button primary">Guardar configuración</button></form></section><section class="panel"><div class="panel-heading"><h2>Cómo funciona el seguimiento</h2></div><div class="settings-body"><h3>1. Detectar un vencimiento</h3><p>La fecha de vencimiento se compara con el día actual. Se descuentan los abonos del período para calcular el saldo pendiente.</p><h3>2. Preparar el recordatorio</h3><p>El mensaje incluye el cliente, el contrato, el mes y el monto pendiente, con copia al administrador.</p><h3>3. Registrar y confirmar el pago</h3><p>El registro actualiza el saldo y prepara un comprobante con el historial de pagos.</p><div class="notice">Los datos se guardan únicamente en este navegador. Esta versión no incluye acceso de usuarios, validación bancaria ni envíos automáticos.</div></div></section></div>`}
function saveSettings(e){e.preventDefault();let f=new FormData(e.target);db.settings={interval:Number(f.get('interval')),email:f.get('email'),phone:f.get('phone'),emailEnabled:f.has('emailEnabled'),whatsapp:f.has('whatsapp')};save();toast('Configuración guardada');render()}
function modal(title,body){$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="Cerrar">×</button></div>${body}`;$('#modal').showModal()}
function closeModal(){$('#modal').close()}const modalActions=label=>`<div class="modal-actions"><button type="button" class="button" onclick="closeModal()">Cancelar</button><button class="button primary">${label}</button></div>`;
function paymentModal(id=''){
  const type=account(id)?.id.startsWith('P')||(!id&&page==='loans')?'loan':'rent';
  modal('Registrar pago',`<div class="payment-tabs" role="tablist" aria-label="Tipo de pago"><button type="button" role="tab" id="rent-tab" aria-controls="payment-panel" onclick="switchPaymentType('rent')">⌂ &nbsp; Arriendo</button><button type="button" role="tab" id="loan-tab" aria-controls="payment-panel" onclick="switchPaymentType('loan')">↗ &nbsp; Deuda / préstamo</button></div><div id="payment-panel" role="tabpanel"></div>`);
  switchPaymentType(type,id);
}
function switchPaymentType(type,id=''){
  const isRent=type==='rent',accounts=allAccounts().filter(a=>a.id.startsWith(isRent?'I':'P'));
  for(const tab of ['rent','loan']){const button=$(`#${tab}-tab`);button.setAttribute('aria-selected',String(tab===type));button.tabIndex=tab===type?0:-1;button.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=e.key==='Home'?'rent':e.key==='End'?'loan':type==='rent'?'loan':'rent';switchPaymentType(next);$(`#${next}-tab`).focus()}}}
  $('#payment-panel').setAttribute('aria-labelledby',`${type}-tab`);
  $('#payment-panel').innerHTML=accounts.length?`<form onsubmit="submitPayment(event)"><p class="payment-intro">${isRent?'Registra el pago de una habitación.':'Registra un abono a un préstamo.'}</p><label class="form-label">${isRent?'Habitación e inquilino':'Préstamo y deudor'}<select name="ref" onchange="updatePayment(this.value)" required>${accounts.map(a=>`<option value="${a.id}" ${a.id===id?'selected':''}>${esc(a.name||a.id)} · ${esc(person(a.person).name)}</option>`).join('')}</select></label><div class="form-grid"><label class="form-label">Período que abona<input type="month" name="period" value="${month}" onchange="updatePayment($('#modal [name=ref]').value)" required></label><label class="form-label">Fecha de recepción<input type="date" name="date" value="${iso()}" max="${iso()}" required></label><label class="form-label full">Monto recibido ($)<input name="amount" type="number" inputmode="numeric" min="1" step="1" required></label></div><label class="check"><input type="checkbox" name="receipt" checked> Preparar comprobante con historial (sin enviar)</label><p class="payment-intro">Confirma que recibiste el dinero antes de guardar.</p>${modalActions('Registrar '+(isRent?'arriendo':'abono'))}</form>`:`<div class="empty">No hay ${isRent?'arriendos con inquilino':'préstamos'} registrados.</div>`;
  if(accounts.length)updatePayment($('#modal [name=ref]').value);
}
function updatePayment(id){const a=account(id),period=$('#modal [name=period]').value||month;$('#modal [name=amount]').value=balance(a,period)}
function paymentInterest(a,period,amount){
  if(a.name)return 0;
  const payments=db.payments.filter(p=>p.ref===a.id);
  const startingCapital=Math.max(0,a.capital-payments.filter(p=>p.period<period).reduce((sum,p)=>sum+p.capital,0));
  const paidInterest=payments.filter(p=>p.period===period).reduce((sum,p)=>sum+p.interest,0);
  return Math.min(amount,Math.max(0,Math.round(startingCapital*a.rate/100)-paidInterest));
}
function submitPayment(e){e.preventDefault();let f=new FormData(e.target),a=account(f.get('ref')),amount=Number(f.get('amount')),period=f.get('period');if(!a||!Number.isFinite(amount)||amount<=0||!Number.isInteger(amount)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))return toast('Revisa el contrato, período y monto del pago');if(amount>balance(a,period))return toast('El monto supera el saldo del período seleccionado');const interest=paymentInterest(a,period,amount);let p={id:crypto.randomUUID(),ref:a.id,period,date:f.get('date'),amount,interest,capital:amount-interest};if(!a.name&&p.capital>loanRemaining(a))return toast('El abono a capital supera el capital pendiente');db.payments.push(p);if(f.has('receipt'))db.outbox.unshift({subject:`Pago recibido · ${a.id}`,to:person(a.person).email,body:receiptText(p),date:iso()});save();closeModal();render();toast('Pago registrado. Saldo e historial actualizados.')}
function receiptText(p){let a=account(p.ref),who=person(a.person);return `Estimado/a ${who.name}:\n\nHemos recibido su pago de ${monthName(p.period)} por ${money(p.amount)} correspondiente a ${a.name||'su préstamo '+a.id}.\n\nReferencia: ${a.id}\nFecha de recepción: ${date(p.date)}\nCapital: ${money(p.capital)} · Intereses: ${money(p.interest)}\nSaldo del período: ${money(balance(a,p.period))}\n\nPAGOS REALIZADOS\n${db.payments.filter(x=>x.ref===p.ref).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>`${date(x.date)} · ${monthName(x.period)} · ${money(x.amount)}`).join('\n')}\n\nPara consultas: ${db.settings.email}\nTeléfono: ${db.settings.phone}\n\nAtentamente, Administración Antonini`}
function receipt(id){let p=db.payments.find(p=>p.id===id);modal('Comprobante de pago',`<div class="message">${esc(receiptText(p))}</div><div class="modal-actions"><button class="button" onclick="downloadReceipt('${id}')">↓ Descargar comprobante</button><button class="button primary" onclick="closeModal()">Listo</button></div>`)}
function download(content,name,type='text/plain;charset=utf-8'){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function downloadReceipt(id){download(receiptText(db.payments.find(p=>p.id===id)),`comprobante-${id.slice(0,8)}.txt`)}
function reminderText(a){return `Estimado/a ${person(a.person).name}:\n\nNo hemos recibido el pago completo de ${monthName()} correspondiente a ${a.name||'su préstamo '+a.id}.\n\nMonto pendiente: ${money(balance(a))}\nReferencia: ${a.id}\n\nLe pedimos que realice su pago a la brevedad. Para más detalles, contáctese con ${db.settings.email}, teléfono ${db.settings.phone}.\n\nSi ya realizó el pago, favor hacer caso omiso de este mensaje.\n\nAtentamente, Administración Antonini`}
function reminder(id){let a=account(id);modal(`Recordatorio · ${id}`,`<p class="subtitle" style="margin-bottom:15px">Para: ${esc(person(a.person).email)} · Copia al administrador</p><div class="message">${esc(reminderText(a))}</div><div class="modal-actions"><button class="button primary" onclick="queueReminder('${id}')">Guardar borrador</button></div>`)}
function queueReminder(id){let a=account(id);db.outbox.unshift({subject:`${id} · Pago pendiente de ${monthName()}`,to:person(a.person).email,body:reminderText(a),date:iso(),ref:id});save();closeModal();render();toast('Borrador guardado. No se ha enviado ningún mensaje.')}
function prepareReminders(){let count=0;for(let a of allAccounts().filter(late)){if(db.outbox.some(o=>o.ref===a.id&&Math.floor((current-new Date(o.date+'T00:00:00'))/86400000)<db.settings.interval))continue;db.outbox.unshift({subject:`${a.id} · Pago pendiente de ${monthName()}`,to:person(a.person).email,body:reminderText(a),date:iso(),ref:a.id});count++}save();render();toast(`${count} borradores preparados. No se enviaron mensajes.`)}
function servicesModal(id){let r=db.rooms.find(r=>r.id===id);modal('Equipamiento de la habitación',`<p class="subtitle" style="margin-bottom:20px">Agrega elementos y describe su tipo o estado de entrega.</p><form onsubmit="saveServices(event,'${id}')"><div id="service-list">${r.services.map(serviceInputs).join('')}</div><button type="button" class="button" onclick="$('#service-list').insertAdjacentHTML('beforeend',serviceInputs(['','']))">＋ Agregar elemento</button>${modalActions('Guardar detalle')}</form>`)}
function serviceInputs([k,v]){return `<div class="service-row"><input name="service" value="${esc(k)}" placeholder="Ej. Cama" aria-label="Elemento" required><input name="description" value="${esc(v)}" placeholder="Ej. Matrimonial" aria-label="Descripción" required><button type="button" onclick="this.parentElement.remove()" aria-label="Eliminar elemento">×</button></div>`}
function saveServices(e,id){e.preventDefault();let f=new FormData(e.target);db.rooms.find(r=>r.id===id).services=f.getAll('service').map((k,i)=>[k,f.getAll('description')[i]]);save();closeModal();render();toast('Detalle de habitación actualizado')}
const personOptions=(blank=false)=>`${blank?'<option value="">Sin asignar</option>':''}${db.people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}`;
function newPerson(){modal('Agregar persona',`<form onsubmit="submitPerson(event)"><div class="form-grid"><label class="form-label full">Nombre completo<input name="name" required></label><label class="form-label">Correo<input type="email" name="email" required></label><label class="form-label">Teléfono<input name="phone" required></label><label class="form-label full">Dirección<input name="address" required></label></div>${modalActions('Guardar persona')}</form>`)}
function submitPerson(e){e.preventDefault();let f=new FormData(e.target);db.people.push({id:'C'+String(db.people.length+1).padStart(3,'0'),...Object.fromEntries(f)});save();closeModal();render();toast('Persona registrada')}
function newRoom(){modal('Nueva habitación',`<form onsubmit="submitRoom(event)"><div class="form-grid"><label class="form-label">Nombre<input name="name" placeholder="Habitación 05" required></label><label class="form-label">Inmueble<input name="property" required></label><label class="form-label">Mensualidad ($)<input name="amount" type="number" min="1" step="1" required></label><label class="form-label">Día de vencimiento<input name="day" type="number" min="1" max="28" value="5" required></label><label class="form-label full">Inquilino<select name="person">${personOptions(true)}</select></label></div>${modalActions('Crear habitación')}</form>`)}
function submitRoom(e){e.preventDefault();let f=new FormData(e.target);db.rooms.push({...Object.fromEntries(f),id:'I'+String(400901+db.rooms.length),amount:Number(f.get('amount')),day:Number(f.get('day')),services:[]});save();closeModal();render();toast('Habitación creada')}
function assignTenant(id){modal('Asignar inquilino',`<form onsubmit="submitTenant(event,'${id}')"><label class="form-label">Persona<select name="person">${personOptions()}</select></label><label class="form-label">Depósito ($)<input name="deposit" type="number" min="0" step="1" value="0" required></label>${modalActions('Asignar inquilino')}</form>`)}
function submitTenant(e,id){e.preventDefault();let f=new FormData(e.target);Object.assign(db.rooms.find(r=>r.id===id),{person:f.get('person'),deposit:Number(f.get('deposit'))});save();closeModal();render();toast('Inquilino asignado')}
function newLoan(){modal('Nuevo préstamo',`<form onsubmit="submitLoan(event)"><div class="notice">El cálculo usa interés mensual sobre el saldo pendiente. Confirma las condiciones acordadas antes de registrar.</div><div class="form-grid"><label class="form-label full">Deudor<select name="person" required>${personOptions()}</select></label><label class="form-label">Capital ($)<input name="capital" type="number" min="1" step="1" required></label><label class="form-label">Tasa mensual (%)<input name="rate" type="number" min="0" max="100" step="0.01" value="2" required></label><label class="form-label">Cuota mensual ($)<input name="amount" type="number" min="1" step="1" required></label><label class="form-label">Día de vencimiento<input name="day" type="number" min="1" max="28" value="5" required></label><label class="form-label">Aval responsable<select name="guarantor" required>${personOptions()}</select></label><label class="form-label">Capitalista<input name="investor" required></label></div>${modalActions('Crear préstamo')}</form>`)}
function submitLoan(e){e.preventDefault();let f=new FormData(e.target),l={...Object.fromEntries(f),id:'P'+String(db.loans.length+1).padStart(4,'0')};for(let k of ['capital','rate','amount','day'])l[k]=Number(l[k]);if(l.person===l.guarantor)return toast('El aval debe ser otra persona');if(l.amount<=l.capital*l.rate/100)return toast('La cuota debe cubrir los intereses y abonar al capital');db.loans.push(l);save();closeModal();render();toast('Préstamo registrado')}
function exportCSV(){let cell=v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';download('\ufeff'+[['Referencia','Cliente','Fecha','Período','Monto','Capital','Intereses'],...db.payments.map(p=>[p.ref,person(account(p.ref).person).name,p.date,p.period,p.amount,p.capital,p.interest])].map(r=>r.map(cell).join(';')).join('\r\n'),`pagos-antonini-${iso()}.csv`,'text/csv;charset=utf-8');toast('Historial exportado')}
$('#notifications').onclick=()=>go('alerts');$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});render();

function moreMenu(){modal('Más opciones',`<p class="mobile-helper">Administra tus contactos, revisa las cobranzas y configura el seguimiento.</p><div class="more-menu"><button class="button" onclick="closeModal();go('people')">♙ &nbsp; Personas y avales <span>→</span></button><button class="button" onclick="closeModal();go('alerts')">◷ &nbsp; Cobranza y recordatorios <span>→</span></button><button class="button" onclick="closeModal();go('settings')">⚙ &nbsp; Configuración <span>→</span></button><button class="button" onclick="exportCSV()">↓ &nbsp; Exportar pagos <span>↗</span></button></div>`)}
const desktopRender=render;
render=function(){desktopRender();let nav=document.querySelector('.mobile-nav');if(!nav){nav=document.createElement('nav');nav.className='mobile-nav';nav.setAttribute('aria-label','Navegación principal móvil');document.body.appendChild(nav)}nav.innerHTML=[['dashboard','▦','Inicio'],['rooms','⌂','Arriendos'],['loans','↗','Préstamos'],['payments','▤','Pagos'],['more','☰','Más']].map(([id,icon,label])=>`<button ${id===page?'aria-current="page"':''} class="${id===page||(id==='more'&&['people','alerts','settings'].includes(page))?'active':''}" onclick="${id==='more'?'moreMenu()':`go('${id}')`}"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('');let quick=document.querySelector('.mobile-pay');if(!quick){quick=document.createElement('button');quick.className='button primary mobile-pay';quick.textContent='＋ Registrar pago';quick.onclick=()=>paymentModal(selected||'');document.body.appendChild(quick)}quick.style.visibility=['dashboard','rooms','loans','payments'].includes(page)?'visible':'hidden';enhanceTables();};
function enhanceTables(){document.querySelectorAll('table').forEach(table=>{let headers=[...table.querySelectorAll('th')].map(th=>th.textContent);if(!['CLIENTE','DEUDOR / PRÉSTAMO','NOMBRE'].includes(headers[0]))return;table.parentElement.classList.add('cards');table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((td,i)=>td.dataset.label=headers[i]||''))})}
const desktopFilterPayments=filterPayments;filterPayments=function(){desktopFilterPayments();enhanceTables()};render();
